<?php

namespace Tests\Feature\Modules;

use App\Models\Project;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Inertia\Testing\AssertableInertia;
use Laravel\Sanctum\Sanctum;
use Starter\Ai\Agents\ToolRegistry;
use Tests\Concerns\CreatesAiCatalog;
use Tests\TestCase;

/**
 * Projects module (generated by starter:make-module): permissions,
 * validation, audit, API, AI tools.
 */
class ProjectsTest extends TestCase
{
    use CreatesAiCatalog, RefreshDatabase;

    /**
     * @param  array<string, mixed>  $overrides
     * @return array<string, mixed>
     */
    protected function payload(array $overrides = []): array
    {
        return [
            'name' => 'Sample name',
            'code' => 'Sample code',
            'description' => 'A longer description.',
            'status' => 'active',
            'starts_on' => '2026-03-15',
            'due_on' => '2026-03-15',
            'budget' => '1.55',
            'is_billable' => true,
            ...$overrides,
        ];
    }

    public function test_readers_see_the_list_but_cannot_change_it(): void
    {
        $project = Project::factory()->create();
        $reader = $this->userWithRole('reader');

        $this->get(route('projects.index'))->assertRedirect(route('login'));

        $this->actingAs($reader)->get(route('projects.index'))
            ->assertOk()
            ->assertInertia(fn (AssertableInertia $page) => $page
                ->component('projects/Index')
                ->has('projects.data', 1)
                ->where('can.create', false));

        $this->actingAs($reader)->get(route('projects.create'))->assertForbidden();
        $this->actingAs($reader)->post(route('projects.store'), $this->payload())->assertForbidden();
        $this->actingAs($reader)->put(route('projects.update', $project), $this->payload())->assertForbidden();
        $this->actingAs($reader)->delete(route('projects.destroy', $project))->assertForbidden();
        $this->assertSame(1, Project::query()->count());

        $this->actingAs($this->userWithRole([]))->get(route('projects.index'))->assertForbidden();
    }

    public function test_editors_create_update_and_delete_with_audit(): void
    {
        $editor = $this->userWithRole('editor');

        $this->actingAs($editor)->post(route('projects.store'), $this->payload(['name' => '']))
            ->assertSessionHasErrors('name');

        $this->actingAs($editor)->post(route('projects.store'), $this->payload())
            ->assertRedirect(route('projects.index'));

        $project = Project::query()->sole();
        $this->assertSame($editor->id, $project->created_by);
        $this->assertDatabaseHas('audit_events', ['action' => 'projects.created', 'actor_id' => $editor->id]);

        $this->actingAs($editor)->get(route('projects.edit', $project))
            ->assertOk()
            ->assertInertia(fn (AssertableInertia $page) => $page->component('projects/Edit')->where('project.id', $project->id));

        $this->actingAs($editor)->put(route('projects.update', $project), $this->payload(['name' => 'Renamed project']))
            ->assertRedirect(route('projects.index'));
        $this->assertSame('Renamed project', $project->refresh()->name);
        $this->assertDatabaseHas('audit_events', ['action' => 'projects.updated', 'actor_id' => $editor->id]);

        $this->actingAs($editor)->get(route('projects.index', ['search' => 'no such project']))
            ->assertInertia(fn (AssertableInertia $page) => $page->has('projects.data', 0));

        // Sorting only accepts the listed columns...
        $this->actingAs($editor)->get(route('projects.index', ['sort' => 'name', 'direction' => 'desc']))
            ->assertInertia(fn (AssertableInertia $page) => $page->has('projects.data', 1)->where('filters.direction', 'desc'));
        $this->actingAs($editor)->get(route('projects.index', ['sort' => 'password']))->assertSessionHasErrors('sort');

        $this->actingAs($editor)->delete(route('projects.destroy', $project))->assertRedirect(route('projects.index'));
        $this->assertModelMissing($project);
        $this->assertDatabaseHas('audit_events', ['action' => 'projects.deleted', 'actor_id' => $editor->id]);
    }

    public function test_the_api_requires_permissions_and_token_abilities(): void
    {
        $project = Project::factory()->create();
        $editor = $this->userWithRole('editor');

        Sanctum::actingAs($editor, ['read']);
        $this->getJson(route('api.v1.projects.index'))->assertOk()->assertJsonPath('data.0.id', $project->id);
        $this->getJson(route('api.v1.projects.show', $project))->assertOk()->assertJsonPath('data.id', $project->id);
        $this->postJson(route('api.v1.projects.store'), $this->payload())->assertForbidden();

        Sanctum::actingAs($editor, ['read', 'write']);
        $id = $this->postJson(route('api.v1.projects.store'), $this->payload())->assertCreated()->json('data.id');
        $this->patchJson(route('api.v1.projects.update', $id), ['name' => 'Renamed project'])
            ->assertOk()
            ->assertJsonPath('data.name', 'Renamed project');
        $this->postJson(route('api.v1.projects.store'), ['name' => ''])->assertUnprocessable();
        $this->deleteJson(route('api.v1.projects.destroy', $id))->assertOk();
        $this->assertDatabaseMissing('projects', ['id' => $id]);

        Sanctum::actingAs($this->userWithRole('reader'), ['read', 'write']);
        $this->deleteJson(route('api.v1.projects.destroy', $project))->assertForbidden();
    }

    public function test_the_ai_tools_use_the_same_actions(): void
    {
        $this->assertContains('projects_list', app(ToolRegistry::class)->names());
        $this->simulatedModel();
        $this->aiAgent(['tools' => ['allowed' => app(ToolRegistry::class)->names(), 'max_steps' => 5, 'confirm_writes' => false]]);
        $project = Project::factory()->create(['name' => 'Renamed project']);

        $stream = $this->actingAs($this->userWithRole('admin'))
            ->post(route('ai.chat.stream'), ['message' => '/tool projects_list {"search": '.json_encode('Renamed project').'}'])
            ->assertOk()
            ->streamedContent();

        $this->assertStringContainsString('\"id\":'.$project->id, $stream);
    }
}
